# Virtual Architects installer for Windows PowerShell. Adds the architect kit to the folder
# you run it in.
#
#   irm @BASE_URL@/install.ps1 | iex
#   & ([scriptblock]::Create((irm @BASE_URL@/install.ps1))) -Update
#
# It never overwrites your files. With -Update it refreshes only the kit's own files
# (agents, commands, the skill, templates, tools and the Copilot copies). It never touches
# docs\architecture\project.yaml or any document you wrote.
# Generated by scripts/build-kit.py. Set $env:VA_BASE_URL to install from another copy of the kit.
param([switch]$Update)
$ErrorActionPreference = "Stop"

$BaseUrl = if ($env:VA_BASE_URL) { $env:VA_BASE_URL } else { "@BASE_URL@" }
$ZipUrl = "$BaseUrl/downloads/virtual-architects-kit.zip"
$ZipSha256 = "@SHA256@"
$Target = (Get-Location).Path
$Tmp = Join-Path ([System.IO.Path]::GetTempPath()) ("va-" + [guid]::NewGuid())
New-Item -ItemType Directory -Path $Tmp | Out-Null

try {
  Write-Host "Downloading the kit from $ZipUrl"
  $Zip = Join-Path $Tmp "kit.zip"
  Invoke-WebRequest -Uri $ZipUrl -OutFile $Zip -UseBasicParsing
  $Got = (Get-FileHash -Algorithm SHA256 $Zip).Hash.ToLower()
  if ($Got -ne $ZipSha256) {
    if (-not $env:VA_BASE_URL) { throw "The download does not match the expected checksum. Nothing was installed." }
    Write-Host "Note: VA_BASE_URL is set and this kit differs from the published one, so its checksum is not verified."
  }
  $Kit = Join-Path $Tmp "kit"
  Expand-Archive -Path $Zip -DestinationPath $Kit

  $Owned = @(
    '^\.claude/agents/', '^\.claude/commands/arch-', '^\.claude/skills/solution-design/', '^\.claude/scripts/',
    '^\.github/agents/', '^\.github/skills/(arch-|solution-design/)', '^\.github/prompts/arch-',
    '^\.github/workflows/(sync-copilot|architecture-docs)\.yml$',
    '^docs/architecture/practice/templates/', '^docs/architecture/tools/',
    '^docs/architecture/(README\.md|LICENSE)$', '^docs/architecture/practice/ea-playbook\.md$'
  )
  $added = 0; $updated = 0; $same = 0; $kept = @()
  Get-ChildItem -Path $Kit -Recurse -File -Force | Sort-Object FullName | ForEach-Object {
    $rel = $_.FullName.Substring($Kit.Length + 1).Replace('\', '/')
    if ($rel -eq 'INSTALL.md') { return }
    $dest = Join-Path $Target $rel
    if (-not (Test-Path $dest)) {
      New-Item -ItemType Directory -Force -Path (Split-Path $dest) | Out-Null
      Copy-Item $_.FullName $dest; $added++
    } elseif ((Get-FileHash $_.FullName).Hash -eq (Get-FileHash $dest).Hash) {
      $same++
    } elseif ($Update -and ($Owned | Where-Object { $rel -match $_ })) {
      Copy-Item $_.FullName $dest -Force; $updated++
    } else {
      $kept += $rel
    }
  }

  Write-Host ""
  Write-Host "Virtual Architects: $added added, $updated updated, $same already up to date."
  if ($kept.Count -gt 0) {
    Write-Host "Kept your version of:"; $kept | ForEach-Object { Write-Host "  $_" }
    if (-not $Update) { Write-Host "Run again with -Update to refresh the kit's own files. Your project.yaml and documents are never replaced." }
  }
  Write-Host ""
  Write-Host "Next: fill in docs\architecture\project.yaml, then in Claude Code or Copilot Chat type /arch-doc."
  Write-Host "Guide: @GUIDE_URL@"
} finally {
  Remove-Item -Recurse -Force $Tmp -ErrorAction SilentlyContinue
}
